{
  "justification": "Immigration and crime dominate salience, signalling strong engagement with group cohesion/boundaries (Loyalty) and order, while the NHS’s prominence and a low social-authority mean (2.35) foreground Care and civil-liberty concerns. A slight tilt toward tax-cut preferences (economic mean 5.54) elevates Proportionality over Equality, though universalist commitments remain visible, and the near-mid EU position (5.16) keeps Loyalty considerations active.",
  "foundations": [
    {
      "foundation": "loyalty",
      "basis": "High salience of Immigration (19.0%), Asylum seekers (4.8%), Relations with EU (2.7%), and National security (1.0%).",
      "weight": 0.23
    },
    {
      "foundation": "care",
      "basis": "NHS (14.2%), Poverty/living standards (1.1%), Asylum seekers (4.8%) as harm reduction, Social inequalities (0.4%).",
      "weight": 0.21
    },
    {
      "foundation": "authority",
      "basis": "Law & order—crime (13.2%) and Terrorism (5.8%) balanced by social position mean 2.35 (liberty over punitive authority).",
      "weight": 0.14
    },
    {
      "foundation": "proportionality",
      "basis": "Economic mean 5.54 (tilt to tax cuts), Taxation salience (3.6%), and Welfare fraud (0.1%).",
      "weight": 0.18
    },
    {
      "foundation": "equality",
      "basis": "NHS (14.2%) as universal provision, Poverty (1.1%), Social inequalities (0.4%), and Education (3.6%).",
      "weight": 0.16
    },
    {
      "foundation": "sanctity",
      "basis": "Values/Morality (0.6%), Drugs (0.5%), Environment (1.8%), and purity/contamination themes linked to Immigration salience.",
      "weight": 0.08
    }
  ]
}
